import java.util.*;class Solution{boolean pal(String s,int l,int r){while(l<r)if(s.charAt(l++)!=s.charAt(r--))return false;return true;}public List<List<Integer>> palindromePairs(String[]w){Map<String,Integer>m=new HashMap<>();for(int i=0;i<w.length;i++)m.put(w[i],i);List<List<Integer>>o=new ArrayList<>();for(int i=0;i<w.length;i++)for(int k=0;k<=w[i].length();k++){if(pal(w[i],0,k-1)){String x=new StringBuilder(w[i].substring(k)).reverse().toString();if(m.containsKey(x)&&m.get(x)!=i)o.add(Arrays.asList(m.get(x),i));}if(k<w[i].length()&&pal(w[i],k,w[i].length()-1)){String x=new StringBuilder(w[i].substring(0,k)).reverse().toString();if(m.containsKey(x)&&m.get(x)!=i)o.add(Arrays.asList(i,m.get(x)));}}return o;}}
